function RecipeEditor({ recipe, onClose, notify }) {
  const { state, execute } = useHotel();
  const allowed = useActionPermission(recipe ? 'RECIPE_UPDATE' : 'RECIPE_CREATE');
  const firstInventory = state.inventory.find((item) => item.status !== 'Archivado')?.id || '';
  const [form, setForm] = useState(recipe ? { ...recipe, ingredients: recipe.ingredients.map((item) => ({ ...item })) } : { name: '', type: 'Cocina', salePrice: 0, ingredients: [{ inventoryId: firstInventory, quantity: 1 }] });
  const updateIngredient = (index, key, value) => setForm({ ...form, ingredients: form.ingredients.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item) });
  const submit = (event) => { event.preventDefault(); const action = recipe ? { type: 'RECIPE_UPDATE', recipeId: recipe.id, payload: form } : { type: 'RECIPE_CREATE', payload: form }; if (run(execute, action, notify, recipe ? 'Receta actualizada' : 'Receta creada', 'Los ingredientes fueron validados sin alterar pedidos existentes.')) onClose(); };
  if (!allowed) return null;
  return <form className="form-grid" onSubmit={submit}><label>Nombre<input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></label><label>Tipo<select value={form.type} onChange={(event) => setForm({ ...form, type: event.target.value })}><option>Cocina</option><option>Bar</option></select></label><label className="span-2">Precio<input type="number" min="0" value={form.salePrice} onChange={(event) => setForm({ ...form, salePrice: event.target.value })} /></label>{form.ingredients.map((ingredient, index) => <div className="form-grid span-2" key={`${index}-${ingredient.inventoryId}`}><label>Ingrediente<select value={ingredient.inventoryId} onChange={(event) => updateIngredient(index, 'inventoryId', event.target.value)}>{state.inventory.filter((item) => item.status !== 'Archivado').map((item) => <option key={item.id} value={item.id}>{item.name} · {item.unit}</option>)}</select></label><label>Cantidad<input type="number" min="0.01" step="any" value={ingredient.quantity} onChange={(event) => updateIngredient(index, 'quantity', event.target.value)} /></label></div>)}<div className="form-actions span-2"><button type="button" className="btn btn-outline" onClick={() => setForm({ ...form, ingredients: [...form.ingredients, { inventoryId: firstInventory, quantity: 1 }] })}>Agregar ingrediente</button><button className="btn btn-primary">Guardar receta</button></div></form>;
}

export function P1FoodBarView({ notify }) {
  const { state, execute } = useHotel();
  const [editor, setEditor] = useState(undefined);
  const [reasonOperation, setReasonOperation] = useState(null);
  const transition = (recipe, type) => setReasonOperation({ actionType: type, title: type === 'RECIPE_ARCHIVE' ? 'Archivar receta' : 'Reactivar receta', onConfirm: ({ reason }) => run(execute, { type, recipeId: recipe.id, reason }, notify, type === 'RECIPE_ARCHIVE' ? 'Receta archivada' : 'Receta reactivada', 'Los pedidos existentes conservaron su snapshot de ingredientes.') });
  return <div className="view-container"><PageHeader actionType="RECIPE_CREATE" metadata="Pedidos conservan snapshot" title="Cocina y bar" description="Alta, edición, archivo y reactivación de recetas validadas." action={<PermissionButton actionType="RECIPE_CREATE" className="btn btn-primary" onClick={() => setEditor(null)}>Nueva receta</PermissionButton>} /><div className="operation-cards">{state.recipes.map((recipe) => <article className="card" key={recipe.id}><div className="row-between"><div><span className="eyebrow">{recipe.id} · {recipe.type}</span><h3>{recipe.name}</h3></div><StatusBadge>{recipe.status || 'Activa'}</StatusBadge></div><p>{formatMoney(recipe.salePrice)} · {recipe.ingredients.length} ingrediente(s)</p><div className="inline-actions">{recipe.status !== 'Archivada' ? <><PermissionButton actionType="RECIPE_UPDATE" className="btn btn-outline" onClick={() => setEditor(recipe)}>Editar</PermissionButton><PermissionButton actionType="RECIPE_ARCHIVE" className="btn btn-danger" onClick={() => transition(recipe, 'RECIPE_ARCHIVE')}>Archivar</PermissionButton></> : <PermissionButton actionType="RECIPE_REACTIVATE" className="btn btn-primary" onClick={() => transition(recipe, 'RECIPE_REACTIVATE')}>Reactivar</PermissionButton>}</div></article>)}</div><Dialog open={editor !== undefined} onClose={() => setEditor(undefined)} title={editor ? `Editar ${editor.name}` : 'Nueva receta'} wide><RecipeEditor recipe={editor || null} onClose={() => setEditor(undefined)} notify={notify} /></Dialog><ReasonDialog operation={reasonOperation} onClose={() => setReasonOperation(null)} /></div>;
}

export function P1SurveysView({ notify }) {
  const { state, execute } = useHotel();
  const canRespond = useActionPermission('SURVEY_RESPOND');
  const [selectedId, setSelectedId] = useState(null);
  const [form, setForm] = useState({ overall: 5, cleaning: 5, service: 5, room: 5, food: 5, comment: '', promotionsAuthorized: false });
  const submit = (event) => { event.preventDefault(); if (run(execute, { type: 'SURVEY_RESPOND', surveyId: selectedId, payload: form }, notify, 'Encuesta respondida', 'La respuesta y el consentimiento del cliente se sincronizaron atómicamente.')) setSelectedId(null); };
  return <div className="view-container"><PageHeader metadata="Puntuaciones de 1 a 5" title="Encuestas y fidelización" description="Respuesta pendiente y consentimiento promocional sincronizados." /><div className="operation-cards">{state.surveys.map((survey) => <article className="card" key={survey.id}><div className="row-between"><h3>{survey.id} · {selectClientName(state, survey.clientId)}</h3><StatusBadge>{survey.status}</StatusBadge></div><p>{survey.status === 'Respondida' ? `${survey.overall}/5 · ${survey.comment || 'Sin comentario'}` : 'Pendiente de respuesta'}</p>{survey.status === 'Pendiente' && canRespond ? <button className="btn btn-primary" onClick={() => setSelectedId(survey.id)}>Responder</button> : null}</article>)}</div><Dialog open={Boolean(selectedId)} onClose={() => setSelectedId(null)} title="Responder encuesta">{canRespond ? <form className="form-grid" onSubmit={submit}>{['overall', 'cleaning', 'service', 'room', 'food'].map((key) => <label key={key}>{({ overall: 'General', cleaning: 'Limpieza', service: 'Atención', room: 'Habitación', food: 'Comida' })[key]}<input type="number" min="1" max="5" value={form[key]} onChange={(event) => setForm({ ...form, [key]: event.target.value })} /></label>)}<label className="span-2">Comentario<textarea value={form.comment} onChange={(event) => setForm({ ...form, comment: event.target.value })} /></label><label className="toggle-row span-2"><input type="checkbox" checked={form.promotionsAuthorized} onChange={(event) => setForm({ ...form, promotionsAuthorized: event.target.checked })} /><span>Autoriza comunicaciones promocionales</span></label><button className="btn btn-primary span-2">Guardar respuesta</button></form> : null}</Dialog></div>;
}

export function P1NotificationsView({ navigate, notify }) {
  const { state, execute } = useHotel();
  const canMarkRead = useActionPermission('NOTIFICATION_READ');
  const open = (notification) => { if (!notification.read && canMarkRead) run(execute, { type: 'NOTIFICATION_READ', notificationId: notification.id }, notify, 'Notificación leída', 'El estado de lectura quedó registrado.'); navigate(notification.route); };
  return <div className="view-container"><PageHeader metadata="Lectura individual" title="Notificaciones" description="Cada registro conserva su feedback real y abre el módulo relacionado." /><div className="record-list">{state.notifications.map((item) => <article className="card" key={item.id}><div><strong>{item.title}</strong><span>{item.description}</span><small>{item.read ? `Leída ${formatDateTime(item.readAt)}` : 'Sin leer'}</small></div><button className="btn btn-outline" onClick={() => open(item)}>{item.read ? 'Abrir módulo' : 'Marcar leída y abrir'}</button></article>)}</div></div>;
}
